"""Artifacts generated by a run, by step."""

from __future__ import annotations

from pathlib import Path
from types import SimpleNamespace

from core.models.runtime import RuntimeNodeType
from lib.artifacts.store import ArtifactStore, ensure_artifacts_schema
from lib.database.connection import DatabaseConnection
from lib.plugins.runner import PluginRunner


def test_artifacts_of_runs_keep_their_step(tmp_path: Path) -> None:
    connection = DatabaseConnection(tmp_path / "entropy.db")
    ensure_artifacts_schema(connection)
    store = ArtifactStore(connection)
    report = store.create(
        1,
        "report.html",
        "server_path",
        3,
        "admin",
        server_path="/tmp/report.html",
        classification="generated",
        origin="custom.audit",
        run_id="exec-1",
        step_name="Audit",
    )
    store.create(1, "other.html", "server_path", 3, "admin", run_id="exec-2")
    store.create(2, "elsewhere.html", "server_path", 3, "admin", run_id="exec-1")

    found = store.for_runs(1, ["exec-1"])

    assert [item["id"] for item in found] == [report["id"]]
    assert found[0]["step_name"] == "Audit"
    assert store.for_runs(1, []) == []


def test_old_artifact_tables_gain_the_step_column(tmp_path: Path) -> None:
    connection = DatabaseConnection(tmp_path / "old.db")
    connection.execute(
        "CREATE TABLE artifacts (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL,"
        "name TEXT NOT NULL, source TEXT NOT NULL, server_path TEXT, storage_name TEXT,"
        "size_bytes INTEGER NOT NULL, sha256 TEXT, tags TEXT NOT NULL DEFAULT '[]',"
        "created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')))"
    )
    ensure_artifacts_schema(connection)
    columns = {row["name"] for row in connection.fetchall("PRAGMA table_info(artifacts)")}
    assert "step_name" in columns


def test_current_step_is_found_above_nested_scopes() -> None:
    step = SimpleNamespace(type=RuntimeNodeType.STEP, name="Build", parent=None)
    stage = SimpleNamespace(type=RuntimeNodeType.STAGE, name="inner", parent=step)

    assert PluginRunner._current_step(SimpleNamespace(node=stage)) == "Build"  # type: ignore[arg-type]
    assert PluginRunner._current_step(SimpleNamespace(node=None)) is None  # type: ignore[arg-type]


def test_artifacts_name_the_jobs_execution_not_the_workers(tmp_path: Path) -> None:
    connection = DatabaseConnection(tmp_path / "jobs.db")
    connection.execute("CREATE TABLE workflow_jobs (id INTEGER PRIMARY KEY, execution_id TEXT)")
    connection.execute("INSERT INTO workflow_jobs(id, execution_id) VALUES (162, 'audit_ead333cf')")
    worker = SimpleNamespace(execution=SimpleNamespace(id="audit_f1a67d4b"))

    attached = SimpleNamespace(job_id=162, **vars(worker))
    assert PluginRunner._run_execution_id(attached, connection) == "audit_ead333cf"  # type: ignore[arg-type]
    unknown = SimpleNamespace(job_id=999, **vars(worker))
    assert PluginRunner._run_execution_id(unknown, connection) == "audit_f1a67d4b"  # type: ignore[arg-type]
    cli = SimpleNamespace(job_id=None, **vars(worker))
    assert PluginRunner._run_execution_id(cli, connection) == "audit_f1a67d4b"  # type: ignore[arg-type]
